@Test
public void testExpressions() throws Exception {
    Schema schema = new Schema(Types.NestedField.optional(34, "a", Types.IntegerType.get()));
    Expression[] expressions = new Expression[] { Expressions.alwaysFalse(), Expressions.alwaysTrue(), Expressions.lessThan("x", 5), Expressions.lessThanOrEqual("y", -3), Expressions.greaterThan("z", 0), Expressions.greaterThanOrEqual("t", 129), Expressions.equal("col", "data"), Expressions.notEqual("col", "abc"), Expressions.notNull("maybeNull"), Expressions.isNull("maybeNull2"), Expressions.not(Expressions.greaterThan("a", 10)), Expressions.and(Expressions.greaterThanOrEqual("a", 0), Expressions.lessThan("a", 3)), Expressions.or(Expressions.lessThan("a", 0), Expressions.greaterThan("a", 10)), Expressions.equal("a", 5).bind(schema.asStruct()) };
    for (Expression expression : expressions) {
        Expression copy = TestHelpers.roundTripSerialize(expression);
        Assert.assertTrue("Expression should equal the deserialized copy: " + expression + " != " + copy, equals(expression, copy));
    }
}

