@Test
@SuppressWarnings("unchecked")
public void testLongToIntegerConversion() {
    StructType struct = StructType.of(required(17, "i", Types.IntegerType.get()));
    UnboundPredicate<Long> lt = new UnboundPredicate<>(LT, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Less than above max should be alwaysTrue", Expressions.alwaysTrue(), lt.bind(struct));
    UnboundPredicate<Long> lteq = new UnboundPredicate<>(LT_EQ, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Less than or equal above max should be alwaysTrue", Expressions.alwaysTrue(), lteq.bind(struct));
    UnboundPredicate<Long> gt = new UnboundPredicate<>(GT, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Greater than below min should be alwaysTrue", Expressions.alwaysTrue(), gt.bind(struct));
    UnboundPredicate<Long> gteq = new UnboundPredicate<>(GT_EQ, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Greater than or equal below min should be alwaysTrue", Expressions.alwaysTrue(), gteq.bind(struct));
    UnboundPredicate<Long> gtMax = new UnboundPredicate<>(GT, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Greater than above max should be alwaysFalse", Expressions.alwaysFalse(), gtMax.bind(struct));
    UnboundPredicate<Long> gteqMax = new UnboundPredicate<>(GT_EQ, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Greater than or equal above max should be alwaysFalse", Expressions.alwaysFalse(), gteqMax.bind(struct));
    UnboundPredicate<Long> ltMin = new UnboundPredicate<>(LT, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Less than below min should be alwaysFalse", Expressions.alwaysFalse(), ltMin.bind(struct));
    UnboundPredicate<Long> lteqMin = new UnboundPredicate<>(LT_EQ, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Less than or equal below min should be alwaysFalse", Expressions.alwaysFalse(), lteqMin.bind(struct));
    Expression ltExpr = new UnboundPredicate<>(LT, ref("i"), (long) Integer.MAX_VALUE).bind(struct);
    BoundPredicate<Integer> ltMax = assertAndUnwrap(ltExpr);
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MAX_VALUE, ltMax.literal().value());
    Expression lteqExpr = new UnboundPredicate<>(LT_EQ, ref("i"), (long) Integer.MAX_VALUE).bind(struct);
    BoundPredicate<Integer> lteqMax = assertAndUnwrap(lteqExpr);
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MAX_VALUE, lteqMax.literal().value());
    Expression gtExpr = new UnboundPredicate<>(GT, ref("i"), (long) Integer.MIN_VALUE).bind(struct);
    BoundPredicate<Integer> gtMin = assertAndUnwrap(gtExpr);
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MIN_VALUE, gtMin.literal().value());
    Expression gteqExpr = new UnboundPredicate<>(GT_EQ, ref("i"), (long) Integer.MIN_VALUE).bind(struct);
    BoundPredicate<Integer> gteqMin = assertAndUnwrap(gteqExpr);
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MIN_VALUE, gteqMin.literal().value());
}

