    Assert.assertFalse("Should match: not(true)", shouldRead);
}

@Test
public void testAnd() {
    // this test case must use a real predicate, not alwaysTrue(), or binding will simplify it out
    boolean shouldRead = new StrictMetricsEvaluator(SCHEMA, and(greaterThan("id", 5), lessThanOrEqual("id", 30))).eval(FILE);
    Assert.assertFalse("Should not match: range overlaps data", shouldRead);
    shouldRead = new StrictMetricsEvaluator(SCHEMA, and(lessThan("id", 5), greaterThanOrEqual("id", 0))).eval(FILE);
    Assert.assertFalse("Should match: range does not overlap data", shouldRead);
    shouldRead = new StrictMetricsEvaluator(SCHEMA, and(lessThan("id", 85), greaterThanOrEqual("id", 0))).eval(FILE);
    Assert.assertTrue("Should match: range includes all data", shouldRead);
}

@Test
public void testOr() {
