@Test
public void testPrimitiveTypes() {
    for (Type.PrimitiveType from : PRIMITIVES) {
        Schema fromSchema = new Schema(required(1, "from_field", from));
        for (Type.PrimitiveType to : PRIMITIVES) {
            List<String> errors = CheckCompatibility.writeCompatibilityErrors(new Schema(required(1, "to_field", to)), fromSchema);
            if (TypeUtil.isPromotionAllowed(from, to)) {
                Assert.assertEquals("Should produce 0 error messages", 0, errors.size());
            } else {
                Assert.assertEquals("Should produce 1 error message", 1, errors.size());
                Assert.assertTrue("Should complain that promotion is not allowed", errors.get(0).contains("cannot be promoted to"));
            }
        }
        {
            Schema structSchema = new Schema(required(1, "struct_field", Types.StructType.of(required(2, "from", from))));
            List<String> errors = CheckCompatibility.writeCompatibilityErrors(structSchema, fromSchema);
            Assert.assertEquals("Should produce 1 error message", 1, errors.size());
            Assert.assertTrue("Should complain that primitive to struct is not allowed", errors.get(0).contains("cannot be read as a struct"));
        }
        {
            Schema listSchema = new Schema(required(1, "list_field", Types.ListType.ofRequired(2, from)));
            List<String> errors = CheckCompatibility.writeCompatibilityErrors(listSchema, fromSchema);
            Assert.assertEquals("Should produce 1 error message", 1, errors.size());
            Assert.assertTrue("Should complain that primitive to list is not allowed", errors.get(0).contains("cannot be read as a list"));
        }
        {
            Schema mapSchema = new Schema(required(1, "map_field", Types.MapType.ofRequired(2, 3, Types.StringType.get(), from)));
            List<String> errors = CheckCompatibility.writeCompatibilityErrors(mapSchema, fromSchema);
            Assert.assertEquals("Should produce 1 error message", 1, errors.size());
            Assert.assertTrue("Should complain that primitive to map is not allowed", errors.get(0).contains("cannot be read as a map"));
        }
        {
            Schema mapSchema = new Schema(required(1, "map_field", Types.MapType.ofRequired(2, 3, from, Types.StringType.get())));
            List<String> errors = CheckCompatibility.writeCompatibilityErrors(mapSchema, fromSchema);
            Assert.assertEquals("Should produce 1 error message", 1, errors.size());
            Assert.assertTrue("Should complain that primitive to map is not allowed", errors.get(0).contains("cannot be read as a map"));
        }
    }
}

