    long currentSnapshotId = System.currentTimeMillis();
    Snapshot currentSnapshot = new BaseSnapshot(null, currentSnapshotId, "file:/tmp/manfiest.2.avro");
    TableMetadata expected = new TableMetadata(null, null, "s3://bucket/test/location", System.currentTimeMillis(), 3, schema, spec, ImmutableMap.of("property", "value"), currentSnapshotId, Arrays.asList(previousSnapshot, currentSnapshot));
