@Test
public void testCorrectness() throws IOException {
    Iterable<Record> records = RandomData.generate(COMPLEX_SCHEMA, 250_000, 34139);
    File testFile = temp.newFile();
    Assert.assertTrue("Delete should succeed", testFile.delete());
    try (FileAppender<Record> writer = Parquet.write(Files.localOutput(testFile)).schema(COMPLEX_SCHEMA).build()) {
        writer.addAll(records);
    }
    MessageType readSchema = ParquetSchemaUtil.convert(COMPLEX_SCHEMA, "test");
    // verify that the new read path is correct
    try (ParquetReader<Record> reader = new ParquetReader<>(Files.localInput(testFile), COMPLEX_SCHEMA, ParquetReadOptions.builder().build(), fileSchema -> ParquetAvroValueReaders.buildReader(COMPLEX_SCHEMA, readSchema), Expressions.alwaysTrue())) {
        int i = 0;
        Iterator<Record> iter = records.iterator();
        for (Record actual : reader) {
            Record expected = iter.next();
            Assert.assertEquals("Record " + i + " should match expected", expected, actual);
            i += 1;
        }
    }
}

