@Test
public void testDayPartitionedTimestampFilters() {
    File location = buildPartitionedTable("partitioned_by_day", PARTITION_BY_DAY, "ts_day", "ts");
    DataSourceOptions options = new DataSourceOptions(ImmutableMap.of("path", location.toString()));
    int day = Literal.of("2017-12-21").<Integer>to(Types.DateType.get()).value();
    IcebergSource source = new IcebergSource();
    DataSourceReader unfiltered = source.createReader(options);
    Assert.assertEquals("Unfiltered table should created 2 read tasks", 2, planTasks(unfiltered).size());
    {
        DataSourceReader reader = source.createReader(options);
        pushFilters(reader, Expressions.lessThan("ts", "2017-12-22T00:00:00+00:00"));
        List<DataReaderFactory<UnsafeRow>> tasks = planTasks(reader);
        Assert.assertEquals("Should create one task for 2017-12-21", 1, tasks.size());
        assertEqualsSafe(SCHEMA.asStruct(), expected(5, 6, 7, 8, 9), read(location.toString(), "ts < cast('2017-12-22 00:00:00+00:00' as timestamp)"));
    }
    {
        DataSourceReader reader = source.createReader(options);
        pushFilters(reader, col("ts").cast(DateType$.MODULE$).$eq$eq$eq(lit(day)).expr());
        List<DataReaderFactory<UnsafeRow>> tasks = planTasks(reader);
        Assert.assertEquals("Should create one task for 2017-12-21", 1, tasks.size());
        assertEqualsSafe(SCHEMA.asStruct(), expected(5, 6, 7, 8, 9), read(location.toString(), "cast(ts as date) = date '2017-12-21'"));
    }
    {
        DataSourceReader reader = source.createReader(options);
        pushFilters(reader, to_date(col("ts")).$eq$eq$eq(lit(day)).expr());
        List<DataReaderFactory<UnsafeRow>> tasks = planTasks(reader);
        Assert.assertEquals("Should create one task for 2017-12-21", 1, tasks.size());
        assertEqualsSafe(SCHEMA.asStruct(), expected(5, 6, 7, 8, 9), read(location.toString(), "to_date(ts) = date '2017-12-21'"));
    }
    {
        DataSourceReader reader = source.createReader(options);
        pushFilters(reader, Expressions.and(Expressions.greaterThan("ts", "2017-12-22T06:00:00+00:00"), Expressions.lessThan("ts", "2017-12-22T08:00:00+00:00")));
        List<DataReaderFactory<UnsafeRow>> tasks = planTasks(reader);
        Assert.assertEquals("Should create one task for 2017-12-22", 1, tasks.size());
        assertEqualsSafe(SCHEMA.asStruct(), expected(1, 2), read(location.toString(), "ts > cast('2017-12-22 06:00:00+00:00' as timestamp) and " + "ts < cast('2017-12-22 08:00:00+00:00' as timestamp)"));
    }
}

