@Test
public void testBasicWrite() throws IOException {
    File parent = temp.newFolder("orc");
    File location = new File(parent, "test");
    location.mkdirs();
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.builderFor(SCHEMA).identity("data").build();
    Table table = tables.create(SCHEMA, spec, location.toString());
    table.updateProperties().defaultFormat(FileFormat.ORC).set(OrcConf.COMPRESS.getAttribute(), CompressionKind.NONE.name()).commit();
    List<SimpleRecord> expected = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> df = spark.createDataFrame(expected, SimpleRecord.class);
    // TODO: incoming columns must be ordered according to the table's schema
    df.select("id", "data").write().format("iceberg").mode("append").save(location.toString());
    table.refresh();
    Dataset<Row> result = spark.read().format("iceberg").load(location.toString());
    List<SimpleRecord> actual = result.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Number of rows should match", expected.size(), actual.size());
    Assert.assertEquals("Result rows should match", expected, actual);
}

