@Test
public void testMapOfStructsProjection() throws IOException {
    Schema writeSchema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(5, "locations", Types.MapType.ofOptional(6, 7, Types.StringType.get(), Types.StructType.of(Types.NestedField.required(1, "lat", Types.FloatType.get()), Types.NestedField.required(2, "long", Types.FloatType.get())))));
    Record record = new Record(AvroSchemaUtil.convert(writeSchema, "table"));
    record.put("id", 34L);
    Record l1 = new Record(fromOption(fromOption(record.getSchema().getField("locations").schema()).getValueType()));
    l1.put("lat", 53.992811f);
    l1.put("long", -1.542616f);
    Record l2 = new Record(l1.getSchema());
    l2.put("lat", 52.995143f);
    l2.put("long", -1.539054f);
    record.put("locations", ImmutableMap.of("L1", l1, "L2", l2));
    Schema idOnly = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()));
    Record projected = writeAndRead("id_only", writeSchema, idOnly, record);
    Assert.assertEquals("Should contain the correct id value", 34L, (long) projected.get("id"));
    Assert.assertNull("Should not project locations map", projected.get("locations"));
    projected = writeAndRead("all_locations", writeSchema, writeSchema.select("locations"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    Assert.assertEquals("Should project locations map", record.get("locations"), toStringMap((Map) projected.get("locations")));
    projected = writeAndRead("lat_only", writeSchema, writeSchema.select("locations.lat"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    Map<String, ?> locations = toStringMap((Map) projected.get("locations"));
    Assert.assertNotNull("Should project locations map", locations);
    Assert.assertEquals("Should contain L1 and L2", Sets.newHashSet("L1", "L2"), locations.keySet());
    Record projectedL1 = (Record) locations.get("L1");
    Assert.assertNotNull("L1 should not be null", projectedL1);
    Assert.assertEquals("L1 should contain lat", 53.992811f, (float) projectedL1.get("lat"), 0.000001);
    Assert.assertNull("L1 should not contain long", projectedL1.get("long"));
    Record projectedL2 = (Record) locations.get("L2");
    Assert.assertNotNull("L2 should not be null", projectedL2);
    Assert.assertEquals("L2 should contain lat", 52.995143f, (float) projectedL2.get("lat"), 0.000001);
    Assert.assertNull("L2 should not contain long", projectedL2.get("long"));
    projected = writeAndRead("long_only", writeSchema, writeSchema.select("locations.long"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    locations = toStringMap((Map) projected.get("locations"));
    Assert.assertNotNull("Should project locations map", locations);
    Assert.assertEquals("Should contain L1 and L2", Sets.newHashSet("L1", "L2"), locations.keySet());
    projectedL1 = (Record) locations.get("L1");
    Assert.assertNotNull("L1 should not be null", projectedL1);
    Assert.assertNull("L1 should not contain lat", projectedL1.get("lat"));
    Assert.assertEquals("L1 should contain long", -1.542616f, (float) projectedL1.get("long"), 0.000001);
    projectedL2 = (Record) locations.get("L2");
    Assert.assertNotNull("L2 should not be null", projectedL2);
    Assert.assertNull("L2 should not contain lat", projectedL2.get("lat"));
    Assert.assertEquals("L2 should contain long", -1.539054f, (float) projectedL2.get("long"), 0.000001);
    Schema latitiudeRenamed = new Schema(Types.NestedField.optional(5, "locations", Types.MapType.ofOptional(6, 7, Types.StringType.get(), Types.StructType.of(Types.NestedField.required(1, "latitude", Types.FloatType.get())))));
    projected = writeAndRead("latitude_renamed", writeSchema, latitiudeRenamed, record);
    Assert.assertNull("Should not project id", projected.get("id"));
    locations = toStringMap((Map) projected.get("locations"));
    Assert.assertNotNull("Should project locations map", locations);
    Assert.assertEquals("Should contain L1 and L2", Sets.newHashSet("L1", "L2"), locations.keySet());
    projectedL1 = (Record) locations.get("L1");
    Assert.assertNotNull("L1 should not be null", projectedL1);
    Assert.assertEquals("L1 should contain latitude", 53.992811f, (float) projectedL1.get("latitude"), 0.000001);
    Assert.assertNull("L1 should not contain lat", projectedL1.get("lat"));
    Assert.assertNull("L1 should not contain long", projectedL1.get("long"));
    projectedL2 = (Record) locations.get("L2");
    Assert.assertNotNull("L2 should not be null", projectedL2);
    Assert.assertEquals("L2 should contain latitude", 52.995143f, (float) projectedL2.get("latitude"), 0.000001);
    Assert.assertNull("L2 should not contain lat", projectedL2.get("lat"));
    Assert.assertNull("L2 should not contain long", projectedL2.get("long"));
}

