    p1.put("y", 2);
    Record p2 = new Record(p1.getSchema());
    p2.put("x", 3);
    p2.put("y", null);
    record.put("points", ImmutableList.of(p1, p2));
    Schema idOnly = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()));
